public static int calculateTimeNeeded(int N) {
    // The minimal time grows linearly with the number of people: 2 minutes for each extra person
    // beyond the third person. For N <= 3, no time is needed.
    int time = 2 * (N - 3);
    return Math.max(0, time);
}

