public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to reduce search space
    int minIndex = 0;
    for (int i = 1; i < strings.size(); i++) {
        if (strings.get(i).length() < strings.get(minIndex).length()) {
            minIndex = i;
        }
    }
    String base = strings.get(minIndex);
    int baseLen = base.length();

    for (int len = baseLen; len > 0; len--) {
        java.util.Set<String> substrings = new java.util.HashSet<>();
        for (int i = 0; i + len <= baseLen; i++) {
            substrings.add(base.substring(i, i + len));
        }
        for (String sub : substrings) {
            boolean ok = true;
            String reverseSub = new StringBuilder(sub).reverse().toString();
            for (int s = 0; s < strings.size(); s++) {
                if (s == minIndex) {
                    continue;
                }
                String current = strings.get(s);
                if (!(current.contains(sub) || current.contains(reverseSub))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

